INSERT INTO feature VALUES('editor-session-trace','editor','Replayable editor session traces','language-server','implemented','notable',NULL,'A server asked at `initialize` writes every message it reads and writes, and each quiet lapse and settlement its loop meets, one line each to the file the client names, and a replay meets each line again on a fresh server, parting at the first answer that differs, so a session recorded through `gandr lsp` replays as a test. Beside it, a real VS Code at the extension''s floor opens a corpus source with the extension alone, types a definition and is answered exactly one hover, in the server''s HTML (`mise run check:vscode-smoke`).','surface-lsp','crates/surface-lsp/tests/replay.rs crates/surface-lsp/src/session_trace.rs contrib/gandr-vscode/src/smoke/scene.ts',NULL,'#394');
